<div class="community-markdown-toolbar" role="toolbar" aria-label="Форматирование текста">
    <div class="community-markdown-toolbar__buttons">
        <button type="button" data-markdown-format="bold" title="Жирный (Ctrl+B)" aria-label="Жирный"><x-community.icon name="bold" size="17" /></button>
        <button type="button" data-markdown-format="italic" title="Курсив (Ctrl+I)" aria-label="Курсив"><x-community.icon name="italic" size="17" /></button>
        <button type="button" data-markdown-format="strike" title="Зачёркнутый" aria-label="Зачёркнутый"><x-community.icon name="strikethrough" size="17" /></button>
        <button type="button" data-markdown-format="heading" title="Заголовок" aria-label="Заголовок"><x-community.icon name="heading" size="17" /></button>
        <button type="button" data-markdown-format="link" title="Ссылка (Ctrl+K)" aria-label="Ссылка"><x-community.icon name="link" size="17" /></button>
        <button type="button" data-markdown-format="list" title="Маркированный список" aria-label="Маркированный список"><x-community.icon name="list" size="17" /></button>
        <button type="button" data-markdown-format="numbered-list" title="Нумерованный список" aria-label="Нумерованный список"><x-community.icon name="list-numbers" size="17" /></button>
        <button type="button" data-markdown-format="quote" title="Цитата" aria-label="Цитата"><x-community.icon name="blockquote" size="17" /></button>
        <button type="button" data-markdown-format="code" title="Код в строке" aria-label="Код в строке"><x-community.icon name="code" size="17" /></button>
        <button type="button" data-markdown-format="code-block" title="Блок кода" aria-label="Блок кода"><x-community.icon name="code-dots" size="17" /></button>
        <button type="button" data-markdown-format="table" title="Таблица" aria-label="Таблица"><x-community.icon name="table" size="17" /></button>
    </div>
    <button class="community-markdown-toolbar__preview-toggle" type="button" data-markdown-preview-toggle aria-pressed="false">Предпросмотр</button>
</div>
